/** Attributes of the monitor notification rule. */
export type MonitorNotificationRuleAttributes = {
  conditional_recipients?: MonitorNotificationRuleConditionalRecipients;
  filter?: MonitorNotificationRuleFilter;
  name: MonitorNotificationRuleName;
  recipients?: MonitorNotificationRuleRecipients;
};

/** A conditional recipient rule composed of a `scope` (the matching condition) and `recipients` (who to notify when it matches). */
export type MonitorNotificationRuleCondition = {
  /** A list of recipients to notify. Uses the same format as the monitor `message` field. Must not start with an '@'. */
  recipients: MonitorNotificationRuleRecipients;
  scope: MonitorNotificationRuleConditionScope;
};

/** Defines the condition under which the recipients are notified. Supported formats: - Monitor status condition using `transition_type:<status>`, for example `transition_type:is_alert`. - A single tag key:value pair, for example `env:prod`. */
export type MonitorNotificationRuleConditionScope = string;

/** Use conditional recipients to define different recipients for different situations. Cannot be used with `recipients`. */
export type MonitorNotificationRuleConditionalRecipients = {
  /** Conditions of the notification rule. */
  conditions: (MonitorNotificationRuleCondition)[];
  /** If none of the `conditions` applied, `fallback_recipients` will get notified. */
  fallback_recipients?: MonitorNotificationRuleRecipients;
};

/** Request for creating a monitor notification rule. */
export type MonitorNotificationRuleCreateRequest = {
  data: MonitorNotificationRuleCreateRequestData;
};

/** Object to create a monitor notification rule. */
export type MonitorNotificationRuleCreateRequestData = {
  attributes: MonitorNotificationRuleAttributes;
  type?: MonitorNotificationRuleResourceType;
};

