/** The `sensitive_data_scanner` processor detects and optionally redacts sensitive data in log events.  **Supported pipeline types:** logs */
export type ObservabilityPipelineSensitiveDataScannerProcessor = {
  display_name?: ObservabilityPipelineComponentDisplayName;
  /** Indicates whether the processor is enabled. */
  enabled: boolean;
  /** The unique identifier for this component. Used in other parts of the pipeline to reference this component (for example, as the `input` to downstream components). */
  id: string;
  /** A Datadog search query used to determine which logs this processor targets. */
  include: string;
  /** A list of rules for identifying and acting on sensitive data patterns. */
  rules: (ObservabilityPipelineSensitiveDataScannerProcessorRule)[];
  type: ObservabilityPipelineSensitiveDataScannerProcessorType;
};

/** Defines what action to take when sensitive data is matched. */
export type ObservabilityPipelineSensitiveDataScannerProcessorAction = ObservabilityPipelineSensitiveDataScannerProcessorActionRedact | ObservabilityPipelineSensitiveDataScannerProcessorActionHash | ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedact;

/** Configuration for hashing matched sensitive values. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionHash = {
  action: ObservabilityPipelineSensitiveDataScannerProcessorActionHashAction;
  /** Optional settings for the hash action. When omitted or empty, matched sensitive data is replaced with a deterministic hashed value that preserves structure for analytics while protecting the original content. Reserved for future hash configuration (for example, algorithm or salt). */
  options?: { [key: string]: unknown };
};

/** Action type that replaces the matched sensitive data with a hashed representation, preserving structure while securing content. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionHashAction = "hash";

/** Configuration for partially redacting matched sensitive data. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedact = {
  action: ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactAction;
  options: ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactOptions;
};

/** Action type that redacts part of the sensitive data while preserving a configurable number of characters, typically used for masking purposes (e.g., show last 4 digits of a credit card). */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactAction = "partial_redact";

/** Controls how partial redaction is applied, including character count and direction. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactOptions = {
  /** Number of characters to leave visible from the start or end of the matched value; the rest are redacted. */
  characters: number;
  direction: ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactOptionsDirection;
};

/** Indicates whether to redact characters from the first or last part of the matched value. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionPartialRedactOptionsDirection = "first" | "last";

/** Configuration for completely redacting matched sensitive data. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionRedact = {
  action: ObservabilityPipelineSensitiveDataScannerProcessorActionRedactAction;
  options: ObservabilityPipelineSensitiveDataScannerProcessorActionRedactOptions;
};

/** Action type that completely replaces the matched sensitive data with a fixed replacement string to remove all visibility. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionRedactAction = "redact";

/** Configuration for fully redacting sensitive data. */
export type ObservabilityPipelineSensitiveDataScannerProcessorActionRedactOptions = {
  /** The string used to replace matched sensitive data (for example, "***" or "[REDACTED]"). */
  replace: string;
};

/** Defines a custom regex-based pattern for identifying sensitive data in logs. */
export type ObservabilityPipelineSensitiveDataScannerProcessorCustomPattern = {
  options: ObservabilityPipelineSensitiveDataScannerProcessorCustomPatternOptions;
  type: ObservabilityPipelineSensitiveDataScannerProcessorCustomPatternType;
};

/** Options for defining a custom regex pattern. */
export type ObservabilityPipelineSensitiveDataScannerProcessorCustomPatternOptions = {
  /** Human-readable description providing context about a sensitive data scanner rule */
  description?: string;
  /** A regular expression used to detect sensitive values. Must be a valid regex. */
  rule: string;
};

/** Indicates a custom regular expression is used for matching. */
export type ObservabilityPipelineSensitiveDataScannerProcessorCustomPatternType = "custom";

/** Configuration for keywords used to reinforce sensitive data pattern detection. */
export type ObservabilityPipelineSensitiveDataScannerProcessorKeywordOptions = {
  /** A list of keywords to match near the sensitive pattern. */
  keywords: (string)[];
  /** Maximum number of tokens between a keyword and a sensitive value match. */
  proximity: number;
};

/** Specifies a pattern from Datadog’s sensitive data detection library to match known sensitive data types. */
export type ObservabilityPipelineSensitiveDataScannerProcessorLibraryPattern = {
  options: ObservabilityPipelineSensitiveDataScannerProcessorLibraryPatternOptions;
  type: ObservabilityPipelineSensitiveDataScannerProcessorLibraryPatternType;
};

/** Options for selecting a predefined library pattern and enabling keyword support. */
export type ObservabilityPipelineSensitiveDataScannerProcessorLibraryPatternOptions = {
  /** Human-readable description providing context about a sensitive data scanner rule */
  description?: string;
  /** Identifier for a predefined pattern from the sensitive data scanner pattern library. */
  id: string;
  /** Whether to augment the pattern with recommended keywords (optional). */
  use_recommended_keywords?: boolean;
};

/** Indicates that a predefined library pattern is used. */
export type ObservabilityPipelineSensitiveDataScannerProcessorLibraryPatternType = "library";

/** Pattern detection configuration for identifying sensitive data using either a custom regex or a library reference. */
export type ObservabilityPipelineSensitiveDataScannerProcessorPattern = ObservabilityPipelineSensitiveDataScannerProcessorCustomPattern | ObservabilityPipelineSensitiveDataScannerProcessorLibraryPattern;

/** Defines a rule for detecting sensitive data, including matching pattern, scope, and the action to take. */
export type ObservabilityPipelineSensitiveDataScannerProcessorRule = {
  keyword_options?: ObservabilityPipelineSensitiveDataScannerProcessorKeywordOptions;
  /** A name identifying the rule. */
  name: string;
  on_match: ObservabilityPipelineSensitiveDataScannerProcessorAction;
  pattern: ObservabilityPipelineSensitiveDataScannerProcessorPattern;
  scope: ObservabilityPipelineSensitiveDataScannerProcessorScope;
  /** Tags assigned to this rule for filtering and classification. */
  tags?: (string)[];
};

/** Determines which parts of the log the pattern-matching rule should be applied to. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScope = ObservabilityPipelineSensitiveDataScannerProcessorScopeInclude | ObservabilityPipelineSensitiveDataScannerProcessorScopeExclude | ObservabilityPipelineSensitiveDataScannerProcessorScopeAll;

/** Applies scanning across all available fields. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeAll = {
  target: ObservabilityPipelineSensitiveDataScannerProcessorScopeAllTarget;
};

/** Applies the rule to all fields. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeAllTarget = "all";

/** Excludes specific fields from sensitive data scanning. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeExclude = {
  options: ObservabilityPipelineSensitiveDataScannerProcessorScopeOptions;
  target: ObservabilityPipelineSensitiveDataScannerProcessorScopeExcludeTarget;
};

/** Excludes specific fields from processing. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeExcludeTarget = "exclude";

/** Includes only specific fields for sensitive data scanning. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeInclude = {
  options: ObservabilityPipelineSensitiveDataScannerProcessorScopeOptions;
  target: ObservabilityPipelineSensitiveDataScannerProcessorScopeIncludeTarget;
};

/** Applies the rule only to included fields. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeIncludeTarget = "include";

/** Fields to which the scope rule applies. */
export type ObservabilityPipelineSensitiveDataScannerProcessorScopeOptions = {
  /** List of log attribute names (field paths) to which the scope applies. Only these fields are included in or excluded from pattern matching. */
  fields: (string)[];
};

/** The processor type. The value should always be `sensitive_data_scanner`. */
export type ObservabilityPipelineSensitiveDataScannerProcessorType = "sensitive_data_scanner";

