/** The JSON:API type. */
export type VulnerabilitiesType = "vulnerabilities";

/** A single vulnerability */
export type Vulnerability = {
  attributes: VulnerabilityAttributes;
  /** The unique ID for this vulnerability. */
  id: string;
  relationships: VulnerabilityRelationships;
  type: VulnerabilitiesType;
};

/** Advisory associated with the vulnerability. */
export type VulnerabilityAdvisory = {
  /** Vulnerability advisory ID. */
  id: string;
  /** Vulnerability advisory last modification date. */
  last_modification_date?: string;
  /** Vulnerability advisory publish date. */
  publish_date?: string;
};

/** The JSON:API attributes of the vulnerability. */
export type VulnerabilityAttributes = {
  advisory?: VulnerabilityAdvisory;
  /** Vulnerability advisory ID. */
  advisory_id?: string;
  code_location?: CodeLocation;
  /** Vulnerability CVE list. */
  cve_list: (string)[];
  cvss: VulnerabilityCvss;
  dependency_locations?: VulnerabilityDependencyLocations;
  /** Vulnerability description. */
  description: string;
  ecosystem?: VulnerabilityEcosystem;
  /** Vulnerability exposure time in seconds. */
  exposure_time: number;
  /** First detection of the vulnerability in [RFC 3339](https://datatracker.ietf.org/doc/html/rfc3339) format */
  first_detection: string;
  /** Whether the vulnerability has a remediation or not. */
  fix_available: boolean;
  /** Vulnerability language. */
  language: string;
  /** Last detection of the vulnerability in [RFC 3339](https://datatracker.ietf.org/doc/html/rfc3339) format */
  last_detection: string;
  library?: Library;
  /** Vulnerability origin. */
  origin: (string)[];
  /** List of remediations. */
  remediations: (Remediation)[];
  /** Vulnerability `repo_digest` list (when the vulnerability is related to `Image` asset). */
  repo_digests?: (string)[];
  risks: VulnerabilityRisks;
  /** True if the vulnerability affects a package in the host’s running kernel, false if it affects a non-running kernel, and omit if it is not kernel-related. */
  running_kernel?: boolean;
  status: VulnerabilityStatus;
  /** Vulnerability title. */
  title: string;
  tool: VulnerabilityTool;
  type: VulnerabilityType;
};

/** Vulnerability severities. */
export type VulnerabilityCvss = {
  base: Cvss;
  datadog: Cvss;
};

/** Static library vulnerability location. */
export type VulnerabilityDependencyLocations = {
  block: DependencyLocation;
  name?: DependencyLocation;
  version?: DependencyLocation;
};

/** The related vulnerability asset ecosystem. */
export type VulnerabilityEcosystem = "PyPI" | "Maven" | "NuGet" | "Npm" | "RubyGems" | "Go" | "Packagist" | "Deb" | "Rpm" | "Apk" | "Windows" | "Generic" | "MacOs" | "Oci" | "BottleRocket" | "None";

/** Related entities object. */
export type VulnerabilityRelationships = {
  affects: VulnerabilityRelationshipsAffects;
};

/** Relationship type. */
export type VulnerabilityRelationshipsAffects = {
  data: VulnerabilityRelationshipsAffectsData;
};

/** Asset affected by this vulnerability. */
export type VulnerabilityRelationshipsAffectsData = {
  /** The unique ID for this related asset. */
  id: string;
  type: AssetEntityType;
};

/** Vulnerability risks. */
export type VulnerabilityRisks = {
  epss?: Epss;
  /** Vulnerability public exploit availability. */
  exploit_available: boolean;
  /** Vulnerability exploit sources. */
  exploit_sources: (string)[];
  /** Vulnerability exploitation probability. */
  exploitation_probability: boolean;
  /** Vulnerability POC exploit availability. */
  poc_exploit_available: boolean;
};

/** The vulnerability severity. */
export type VulnerabilitySeverity = "Unknown" | "None" | "Low" | "Medium" | "High" | "Critical";

/** The vulnerability status. */
export type VulnerabilityStatus = "Open" | "Muted" | "Remediated" | "InProgress" | "AutoClosed";

/** The vulnerability tool. */
export type VulnerabilityTool = "IAST" | "SCA" | "Infra" | "SAST";

/** The vulnerability type. */
export type VulnerabilityType = "AdminConsoleActive" | "CodeInjection" | "CommandInjection" | "ComponentWithKnownVulnerability" | "DangerousWorkflows" | "DefaultAppDeployed" | "DefaultHtmlEscapeInvalid" | "DirectoryListingLeak" | "EmailHtmlInjection" | "EndOfLife" | "HardcodedPassword" | "HardcodedSecret" | "HeaderInjection" | "HstsHeaderMissing" | "InsecureAuthProtocol" | "InsecureCookie" | "InsecureJspLayout" | "LdapInjection" | "MaliciousPackage" | "MandatoryRemediation" | "NoHttpOnlyCookie" | "NoSameSiteCookie" | "NoSqlMongoDbInjection" | "PathTraversal" | "ReflectionInjection" | "RiskyLicense" | "SessionRewriting" | "SessionTimeout" | "SqlInjection" | "Ssrf" | "StackTraceLeak" | "TrustBoundaryViolation" | "Unmaintained" | "UntrustedDeserialization" | "UnvalidatedRedirect" | "VerbTampering" | "WeakCipher" | "WeakHash" | "WeakRandomness" | "XContentTypeHeaderMissing" | "XPathInjection" | "Xss";

